-- Álbum Eterno Pacto KIDS: los 100 personajes con su ficha completa
-- (nombre, época, color, cita, frase, ¿quién fue?, para leer, lo recordamos por, valor, ¿sabías que?, lo que aprendo)
-- Ejecutar en Supabase → SQL Editor. Se puede repetir: actualiza los textos y conserva las imágenes subidas desde el panel.
on conflict (comunidad_id, col, id) do update set data = public.docs.data || excluded.data, actualizado = now();

select count(*) as laminas_cargadas from public.docs where comunidad_id = public.central_id() and col = 'laminas';
