insert into public.docs (comunidad_id, col, id, data, actualizado) values
  (public.central_id(), 'laminas', 'lamina-001', '{"numero": 1, "nombre": "Adán", "cita": "Génesis 2:7", "frase": "El primer hombre: Dios lo formó del polvo y le dio vida con su aliento.", "seccion": "Los comienzos", "plan": "gratis", "color": "#2FB36B", "quien": "Adán fue el primer hombre. Dios lo formó del polvo de la tierra, le dio vida con su aliento y lo puso en el jardín del Edén para cuidarlo.", "leer": "Génesis 1:26-31; 2:7-20", "recordamos": "Ser el primer hombre y poner nombre a todos los animales.", "valor": "Responsabilidad", "sabias": "Adán significa «hombre» o «tierra», porque Dios lo formó del polvo.", "aprendo": "Dios me creó con amor y me da trabajos importantes para cuidar lo que Él hizo."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-002', '{"numero": 2, "nombre": "Eva", "cita": "Génesis 2:21-23", "frase": "La primera mujer, creada por Dios para acompañar a Adán.", "seccion": "Los comienzos", "plan": "gratis", "color": "#2FB36B", "quien": "Eva fue la primera mujer. Dios la formó para ser compañera de Adán, y fue la madre de todos los seres humanos.", "leer": "Génesis 2:18-25; 3:1-20", "recordamos": "Ser la primera mujer y la madre de todos.", "valor": "Compañerismo", "sabias": "Eva significa «vida», porque es la madre de todos los vivientes.", "aprendo": "Cuando me equivoco, Dios no deja de amarme y me da una nueva oportunidad."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-003', '{"numero": 3, "nombre": "Caín", "cita": "Génesis 4:1-16", "frase": "Se dejó llevar por el enojo; nos enseña a cuidar a nuestro hermano.", "seccion": "Los comienzos", "plan": "gratis", "color": "#2FB36B", "quien": "Caín fue el primer hijo de Adán y Eva. Trabajaba la tierra, pero dejó que la envidia y el enojo crecieran en su corazón.", "leer": "Génesis 4:1-16", "recordamos": "Ser el primer hijo y no cuidar a su hermano Abel.", "valor": "Dominio propio", "sabias": "Dios le advirtió a Caín que dominara el enojo antes de que fuera tarde.", "aprendo": "Puedo pedirle ayuda a Dios para controlar mi enojo y cuidar a mis hermanos."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-004', '{"numero": 4, "nombre": "Abel", "cita": "Génesis 4:2-4", "frase": "Le dio a Dios lo mejor que tenía, con un corazón agradecido.", "seccion": "Los comienzos", "plan": "gratis", "color": "#2FB36B", "quien": "Abel fue el segundo hijo de Adán y Eva. Era pastor de ovejas y le ofreció a Dios lo mejor de su rebaño.", "leer": "Génesis 4:2-4; Hebreos 11:4", "recordamos": "Darle a Dios lo mejor con un corazón sincero.", "valor": "Gratitud", "sabias": "Abel es el primer nombre que aparece en la lista de héroes de la fe de Hebreos 11.", "aprendo": "A Dios le agrada que le dé lo mejor de mí con alegría."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-005', '{"numero": 5, "nombre": "Set", "cita": "Génesis 4:25-26", "frase": "En su tiempo la gente comenzó a invocar el nombre del Señor.", "seccion": "Los comienzos", "plan": "gratis", "color": "#2FB36B", "quien": "Set fue el hijo que Dios le dio a Adán y Eva después de Abel. En su familia la gente comenzó a orar y buscar a Dios.", "leer": "Génesis 4:25-26; 5:3-8", "recordamos": "Que en su tiempo se comenzó a invocar el nombre del Señor.", "valor": "Esperanza", "sabias": "De la familia de Set vienen Enoc, Noé y, mucho después, Jesús.", "aprendo": "Dios siempre trae esperanza, incluso después de momentos tristes."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-006', '{"numero": 6, "nombre": "Enoc", "cita": "Génesis 5:21-24", "frase": "Caminó tan cerca de Dios que Dios se lo llevó con Él.", "seccion": "Los comienzos", "plan": "gratis", "color": "#2FB36B", "quien": "Enoc fue un hombre que caminaba con Dios todos los días. Su amistad con Dios era tan grande que Dios se lo llevó al cielo sin que muriera.", "leer": "Génesis 5:21-24; Hebreos 11:5", "recordamos": "Caminar con Dios y ser llevado al cielo.", "valor": "Amistad con Dios", "sabias": "Enoc fue el papá de Matusalén, el hombre que más años vivió según la Biblia: 969.", "aprendo": "Puedo caminar con Dios cada día hablando con Él y obedeciéndole."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-007', '{"numero": 7, "nombre": "Noé", "cita": "Génesis 6:9-22", "frase": "Obedeció a Dios y construyó el arca para salvar a su familia y a los animales.", "seccion": "Los comienzos", "plan": "gratis", "color": "#2FB36B", "quien": "Noé fue un hombre justo en un mundo que se había olvidado de Dios. Obedeció y construyó un arca enorme para salvar a su familia y a los animales.", "leer": "Génesis 6–9", "recordamos": "Construir el arca y ver el arcoíris de la promesa.", "valor": "Obediencia", "sabias": "El arca medía unos 135 metros de largo: ¡más que una cancha de fútbol!", "aprendo": "Obedezco a Dios aunque otros no lo hagan, porque Él siempre cumple sus promesas."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-008', '{"numero": 8, "nombre": "Sem", "cita": "Génesis 9:18-27", "frase": "Hijo de Noé; de su familia vendría el pueblo de Abraham.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Sem fue uno de los tres hijos de Noé. Estuvo en el arca con su familia y de él descienden Abraham y el pueblo de Israel.", "leer": "Génesis 9:18-27; 11:10-26", "recordamos": "Ser hijo de Noé y antepasado de Abraham.", "valor": "Respeto", "sabias": "La palabra «semita» viene del nombre de Sem.", "aprendo": "Honro a mi familia y sigo el buen ejemplo de quienes aman a Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-009', '{"numero": 9, "nombre": "Job", "cita": "Job 1:1-22", "frase": "Confió en Dios aun cuando lo perdió todo, y Dios lo bendijo.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Job era un hombre bueno y rico que perdió casi todo lo que tenía. Aun con dolor, no se alejó de Dios, y Dios lo bendijo el doble.", "leer": "Job 1–2; 42:10-17", "recordamos": "Mantenerse fiel a Dios en medio del sufrimiento.", "valor": "Paciencia", "sabias": "Job recibió al final el doble de todo lo que había perdido.", "aprendo": "Cuando las cosas son difíciles, puedo seguir confiando en Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-010', '{"numero": 10, "nombre": "Abraham", "cita": "Génesis 12:1-4", "frase": "Salió de su tierra por fe, y Dios le prometió una gran familia.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Abraham dejó su tierra porque Dios se lo pidió. Dios le prometió que tendría una familia tan grande como las estrellas del cielo.", "leer": "Génesis 12:1-9; 15:1-6", "recordamos": "Ser el padre de la fe y creer las promesas de Dios.", "valor": "Fe", "sabias": "Dios le cambió el nombre de Abram a Abraham, que significa «padre de multitudes».", "aprendo": "Puedo creer lo que Dios dice aunque todavía no lo vea."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-011', '{"numero": 11, "nombre": "Sara", "cita": "Génesis 21:1-7", "frase": "Dios le cumplió su promesa: ¡tuvo a Isaac cuando ya era anciana!", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Sara fue la esposa de Abraham. Esperó muchos años un hijo, y cuando ya era anciana Dios le dio a Isaac.", "leer": "Génesis 18:1-15; 21:1-7", "recordamos": "Tener a Isaac a los 90 años.", "valor": "Esperanza", "sabias": "Sara se rio cuando oyó la promesa, y por eso su hijo se llamó Isaac, que significa «risa».", "aprendo": "Para Dios no hay nada imposible."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-012', '{"numero": 12, "nombre": "Lot", "cita": "Génesis 19:15-29", "frase": "Sobrino de Abraham; Dios lo rescató de Sodoma.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Lot era sobrino de Abraham y viajó con él. Eligió vivir cerca de Sodoma, y Dios envió ángeles para rescatarlo antes de que la ciudad fuera destruida.", "leer": "Génesis 13:1-13; 19:15-29", "recordamos": "Ser rescatado de Sodoma.", "valor": "Buenas decisiones", "sabias": "Abraham dejó que Lot eligiera primero la tierra donde quería vivir.", "aprendo": "Elijo con cuidado mis amigos y los lugares donde paso el tiempo."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-013', '{"numero": 13, "nombre": "Agar", "cita": "Génesis 16:7-13", "frase": "En el desierto descubrió que Dios es «el Dios que me ve».", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Agar era una sierva egipcia de Sara. Huyó al desierto triste y sola, y allí un ángel de Dios le habló y la consoló.", "leer": "Génesis 16:1-13; 21:14-19", "recordamos": "Llamar a Dios «el Dios que me ve».", "valor": "Confianza", "sabias": "Agar es la primera persona en la Biblia que le da un nombre a Dios.", "aprendo": "Dios me ve y me cuida, aunque me sienta solo."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-014', '{"numero": 14, "nombre": "Ismael", "cita": "Génesis 21:14-20", "frase": "Dios escuchó su llanto en el desierto y lo cuidó.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Ismael fue hijo de Abraham y Agar. Cuando era niño se quedó sin agua en el desierto, y Dios escuchó su llanto y lo salvó.", "leer": "Génesis 21:9-21", "recordamos": "Que Dios escuchó su voz en el desierto.", "valor": "Confianza", "sabias": "Ismael significa «Dios escucha».", "aprendo": "Dios escucha mi voz cuando le pido ayuda."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-015', '{"numero": 15, "nombre": "Isaac", "cita": "Génesis 22:1-14", "frase": "El hijo de la promesa; Dios proveyó un cordero en su lugar.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Isaac fue el hijo de la promesa que Dios dio a Abraham y Sara. Era un hombre tranquilo que confiaba en Dios.", "leer": "Génesis 22:1-19; 26:17-25", "recordamos": "Que Dios proveyó un cordero en su lugar en el monte Moriah.", "valor": "Mansedumbre", "sabias": "Isaac hacía pozos de agua y, cuando se los quitaban, cavaba otros sin pelear.", "aprendo": "Puedo buscar la paz en vez de pelear."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-016', '{"numero": 16, "nombre": "Rebeca", "cita": "Génesis 24:15-27", "frase": "Fue amable y le dio agua al siervo de Abraham y a sus camellos.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Rebeca fue la esposa de Isaac. Mostró un gran corazón al darle agua al siervo de Abraham y también a sus diez camellos.", "leer": "Génesis 24:10-67", "recordamos": "Ser amable y elegida como esposa de Isaac.", "valor": "Amabilidad", "sabias": "Un camello sediento puede beber más de 100 litros de agua: ¡Rebeca trabajó mucho!", "aprendo": "Ser amable con todos, aunque sea trabajoso, agrada a Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-017', '{"numero": 17, "nombre": "Esaú", "cita": "Génesis 25:27-34", "frase": "Cambió su primogenitura por un plato de comida; luego perdonó a su hermano.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Esaú era el hijo mayor de Isaac, un gran cazador. Cambió su herencia por un plato de lentejas, pero años después perdonó a su hermano Jacob.", "leer": "Génesis 25:27-34; 33:1-11", "recordamos": "Cambiar su primogenitura por comida y abrazar a Jacob.", "valor": "Perdón", "sabias": "Esaú nació pelirrojo y con mucho vello.", "aprendo": "Lo que Dios me da es valioso, y perdonar trae paz a la familia."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-018', '{"numero": 18, "nombre": "Jacob", "cita": "Génesis 28:10-22", "frase": "Soñó con una escalera al cielo y Dios le prometió estar con él.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Jacob fue hijo de Isaac. Al principio hizo trampas, pero Dios lo cambió y lo transformó en el padre de las doce tribus de Israel.", "leer": "Génesis 28:10-22; 32:22-30", "recordamos": "Soñar con la escalera al cielo y recibir el nombre Israel.", "valor": "Transformación", "sabias": "Dios le cambió el nombre a Jacob por Israel, el nombre de todo el pueblo.", "aprendo": "Dios puede cambiar mi corazón y hacerme mejor."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-019', '{"numero": 19, "nombre": "Lea", "cita": "Génesis 29:31-35", "frase": "Aprendió a alabar a Dios: «Esta vez alabaré al Señor».", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Lea fue la primera esposa de Jacob. Se sentía poco querida, pero aprendió a poner su alegría en Dios.", "leer": "Génesis 29:16-35", "recordamos": "Alabar a Dios cuando nació su hijo Judá.", "valor": "Gratitud", "sabias": "De Lea viene la tribu de Judá, la familia del rey David y de Jesús.", "aprendo": "Dios me ama y puedo alabarlo en todo momento."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-020', '{"numero": 20, "nombre": "Raquel", "cita": "Génesis 29:9-20", "frase": "Jacob la amó tanto que trabajó siete años por ella.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Raquel fue la esposa amada de Jacob, que trabajó catorce años para casarse con ella. Fue la mamá de José y de Benjamín.", "leer": "Génesis 29:9-30; 30:22-24", "recordamos": "Ser la mamá de José.", "valor": "Amor", "sabias": "Raquel conoció a Jacob junto a un pozo, cuando llevaba las ovejas de su papá.", "aprendo": "El amor verdadero es paciente."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-021', '{"numero": 21, "nombre": "José", "cita": "Génesis 37:1-11; 50:20", "frase": "Fue vendido por sus hermanos, pero Dios lo usó para salvar a muchos y él los perdonó.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "José era el hijo favorito de Jacob y sus hermanos lo vendieron como esclavo. En Egipto Dios lo cuidó, llegó a gobernar el país y salvó a su familia del hambre.", "leer": "Génesis 37; 41; 45; 50:20", "recordamos": "Su túnica de colores, interpretar sueños y perdonar a sus hermanos.", "valor": "Perdón", "sabias": "José tenía 17 años cuando lo vendieron y 30 cuando llegó a gobernar Egipto.", "aprendo": "Dios puede transformar algo malo en algo bueno, y yo puedo perdonar."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-022', '{"numero": 22, "nombre": "Judá", "cita": "Génesis 44:18-34", "frase": "Se ofreció en lugar de su hermano Benjamín.", "seccion": "Los patriarcas", "plan": "gratis", "color": "#FF8A1A", "quien": "Judá era uno de los hijos de Jacob. Cuando su hermano Benjamín estaba en peligro, se ofreció a quedarse como esclavo en su lugar.", "leer": "Génesis 44:18-34; 49:8-10", "recordamos": "Ofrecerse en lugar de su hermano.", "valor": "Responsabilidad", "sabias": "De la tribu de Judá vienen el rey David y Jesús, «el León de la tribu de Judá».", "aprendo": "Puedo cuidar y proteger a los demás, aunque me cueste."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-023', '{"numero": 23, "nombre": "Moisés", "cita": "Éxodo 3:1-12", "frase": "Dios le habló desde una zarza ardiente y lo envió a liberar a su pueblo.", "seccion": "Éxodo y conquista", "plan": "gratis", "color": "#2E7CF6", "quien": "Moisés fue rescatado del río Nilo cuando era bebé. Dios lo llamó desde una zarza ardiente para liberar a su pueblo de Egipto y le entregó los Diez Mandamientos.", "leer": "Éxodo 3:1-12; 14:21-31; 20:1-17", "recordamos": "Abrir el mar Rojo y recibir las tablas de la ley.", "valor": "Valentía", "sabias": "Moisés significa «sacado de las aguas».", "aprendo": "Dios me da fuerzas para hacer lo que Él me pide, aunque me sienta pequeño."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-024', '{"numero": 24, "nombre": "Aarón", "cita": "Éxodo 4:14-16", "frase": "Hermano de Moisés; hablaba por él ante el faraón.", "seccion": "Éxodo y conquista", "plan": "gratis", "color": "#2E7CF6", "quien": "Aarón era el hermano mayor de Moisés. Hablaba por él ante el faraón y fue el primer sumo sacerdote de Israel.", "leer": "Éxodo 4:10-17; 28:1-4", "recordamos": "Ser el primer sumo sacerdote y su vara que floreció.", "valor": "Servicio", "sabias": "Su vara floreció y dio almendras en una sola noche.", "aprendo": "Puedo ayudar a otros a cumplir lo que Dios les pidió."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-025', '{"numero": 25, "nombre": "Miriam", "cita": "Éxodo 15:20-21", "frase": "Cantó y danzó a Dios después de cruzar el mar Rojo.", "seccion": "Éxodo y conquista", "plan": "gratis", "color": "#2E7CF6", "quien": "Miriam era la hermana de Moisés. De niña cuidó a su hermanito en el río, y después del mar Rojo dirigió a las mujeres en alabanza.", "leer": "Éxodo 2:1-10; 15:20-21", "recordamos": "Cuidar a Moisés bebé y cantar con su pandero.", "valor": "Alabanza", "sabias": "Miriam es la primera mujer llamada profetisa en la Biblia.", "aprendo": "Puedo alabar a Dios con alegría por lo que hace."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-026', '{"numero": 26, "nombre": "Josué", "cita": "Josué 1:9", "frase": "Dios le dijo: «Sé fuerte y valiente», y guió al pueblo a la tierra prometida.", "seccion": "Éxodo y conquista", "plan": "gratis", "color": "#2E7CF6", "quien": "Josué fue el ayudante de Moisés. Después lo reemplazó como líder y guió al pueblo a la tierra prometida.", "leer": "Josué 1:1-9; 6:1-20", "recordamos": "Las murallas de Jericó que cayeron.", "valor": "Valentía", "sabias": "Josué fue uno de los dos espías que confiaron en Dios cuando los demás tuvieron miedo.", "aprendo": "Dios está conmigo, por eso puedo ser fuerte y valiente."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-027', '{"numero": 27, "nombre": "Caleb", "cita": "Números 14:6-9", "frase": "Confió en que Dios les daría la tierra, aunque los demás tenían miedo.", "seccion": "Éxodo y conquista", "plan": "gratis", "color": "#2E7CF6", "quien": "Caleb fue uno de los doce espías. Mientras otros tenían miedo, él confió en que Dios les daría la tierra.", "leer": "Números 13:30; 14:6-9; Josué 14:6-14", "recordamos": "Su fe valiente y pedir una montaña a los 85 años.", "valor": "Fe", "sabias": "Caleb dijo que a los 85 años tenía la misma fuerza que a los 40.", "aprendo": "Cuando confío en Dios, no tengo que dejarme llevar por el miedo."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-028', '{"numero": 28, "nombre": "Rahab", "cita": "Josué 2:1-21", "frase": "Escondió a los espías y un cordón rojo salvó a su familia.", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Rahab vivía en Jericó. Escondió a los espías de Israel porque creyó en el Dios verdadero, y un cordón rojo en su ventana salvó a su familia.", "leer": "Josué 2; 6:22-25", "recordamos": "El cordón rojo en su ventana.", "valor": "Fe", "sabias": "Rahab aparece en la lista de los antepasados de Jesús.", "aprendo": "Nunca es tarde para creer en Dios y elegir su camino."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-029', '{"numero": 29, "nombre": "Débora", "cita": "Jueces 4:4-9", "frase": "Jueza y profetisa valiente que guió a Israel.", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Débora fue jueza y profetisa de Israel. Se sentaba bajo una palmera para ayudar al pueblo y animó al ejército a confiar en Dios.", "leer": "Jueces 4–5", "recordamos": "Ser una líder sabia y valiente.", "valor": "Liderazgo", "sabias": "Al lugar donde atendía al pueblo le decían «la palmera de Débora».", "aprendo": "Puedo animar a otros a confiar en Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-030', '{"numero": 30, "nombre": "Gedeón", "cita": "Jueces 6:11-16", "frase": "Con solo 300 hombres y la ayuda de Dios venció a un gran ejército.", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Gedeón se sentía débil y pequeño, pero Dios lo llamó «hombre valiente». Con solo 300 hombres, cántaros y trompetas venció a un ejército enorme.", "leer": "Jueces 6:11-16; 7:16-22", "recordamos": "Ganar con 300 hombres, trompetas y antorchas.", "valor": "Obediencia", "sabias": "Gedeón le pidió a Dios una señal con un vellón de lana mojado y seco.", "aprendo": "Dios me ve como Él me hace: ¡valiente!"}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-031', '{"numero": 31, "nombre": "Jefté", "cita": "Jueces 11:1-11", "frase": "Lo rechazaron, pero Dios lo usó para defender a su pueblo.", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Jefté fue rechazado por su familia, pero cuando Israel estuvo en peligro lo buscaron para que los guiara, y Dios le dio la victoria.", "leer": "Jueces 11:1-11, 29-33", "recordamos": "Ser un líder rechazado que Dios usó.", "valor": "Perseverancia", "sabias": "Jefté aparece en la lista de héroes de la fe de Hebreos 11.", "aprendo": "Aunque otros me rechacen, Dios tiene un propósito para mí."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-032', '{"numero": 32, "nombre": "Sansón", "cita": "Jueces 16:28-30", "frase": "Dios le dio una fuerza enorme; al final volvió a clamar a Dios.", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Sansón recibió de Dios una fuerza enorme mientras guardaba su promesa. Se equivocó muchas veces, pero al final volvió a clamar a Dios.", "leer": "Jueces 13:24-25; 16:4-31", "recordamos": "Su fuerza increíble y su cabello largo.", "valor": "Arrepentimiento", "sabias": "Sansón venció a un león con sus propias manos.", "aprendo": "Mi fuerza viene de Dios y siempre puedo volver a Él."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-033', '{"numero": 33, "nombre": "Dalila", "cita": "Jueces 16:4-21", "frase": "Engañó a Sansón; nos enseña a elegir bien en quién confiar.", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Dalila fue una mujer que engañó a Sansón para descubrir el secreto de su fuerza y lo entregó a sus enemigos.", "leer": "Jueces 16:4-21", "recordamos": "Engañar a Sansón.", "valor": "Lealtad", "sabias": "Sansón le mintió tres veces antes de contarle su secreto.", "aprendo": "Elijo con cuidado en quién confiar y soy leal con mis amigos."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-034', '{"numero": 34, "nombre": "Rut", "cita": "Rut 1:16", "frase": "Fiel a Noemí: «Tu pueblo será mi pueblo, y tu Dios mi Dios».", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Rut no era israelita, pero decidió quedarse con su suegra Noemí y seguir al Dios de Israel. Trabajó recogiendo trigo para cuidarla.", "leer": "Rut 1:16-17; 2:1-12", "recordamos": "Su fidelidad a Noemí.", "valor": "Fidelidad", "sabias": "Rut fue la bisabuela del rey David.", "aprendo": "Ser fiel y cuidar a mi familia agrada a Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-035', '{"numero": 35, "nombre": "Noemí", "cita": "Rut 1:1-22", "frase": "Volvió triste a Belén, y Dios llenó otra vez su vida de alegría.", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Noemí perdió a su esposo y a sus hijos, y volvió a Belén muy triste. Dios la acompañó y le devolvió la alegría con su nieto Obed.", "leer": "Rut 1:1-22; 4:13-17", "recordamos": "Volver a Belén con Rut.", "valor": "Esperanza", "sabias": "Noemí significa «agradable»; en su tristeza pidió que la llamaran Mara, «amarga».", "aprendo": "Dios puede cambiar mi tristeza en alegría."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-036', '{"numero": 36, "nombre": "Booz", "cita": "Rut 2:1-12", "frase": "Hombre bondadoso que cuidó de Rut y Noemí.", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Booz era un hombre trabajador y generoso de Belén. Protegió a Rut, la dejó recoger trigo en sus campos y se casó con ella.", "leer": "Rut 2:1-16; 4:9-13", "recordamos": "Su bondad con Rut.", "valor": "Generosidad", "sabias": "Booz fue el bisabuelo del rey David.", "aprendo": "Puedo ser generoso con quien lo necesita."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-037', '{"numero": 37, "nombre": "Ana", "cita": "1 Samuel 1:9-20", "frase": "Oró con todo su corazón y Dios le dio a Samuel.", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Ana deseaba mucho un hijo y oró con todo su corazón en el templo. Dios le respondió con Samuel, y ella cumplió su promesa de dedicarlo al Señor.", "leer": "1 Samuel 1:9-28; 2:1-10", "recordamos": "Orar en el templo y ser la mamá de Samuel.", "valor": "Oración", "sabias": "Samuel significa «Dios escuchó».", "aprendo": "Puedo contarle a Dios todo lo que hay en mi corazón."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-038', '{"numero": 38, "nombre": "Samuel", "cita": "1 Samuel 3:1-10", "frase": "De niño escuchó la voz de Dios: «Habla, que tu siervo escucha».", "seccion": "Jueces y transición al reino", "plan": "gratis", "color": "#8B5CF6", "quien": "Samuel creció en el templo y desde niño escuchó la voz de Dios. Fue profeta y juez, y ungió a los primeros reyes de Israel.", "leer": "1 Samuel 3:1-10; 16:1-13", "recordamos": "Decir «Habla, Señor, que tu siervo escucha».", "valor": "Escuchar a Dios", "sabias": "Samuel ungió a Saúl y a David, los dos primeros reyes.", "aprendo": "Dios también habla a los niños, y yo quiero escucharlo."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-039', '{"numero": 39, "nombre": "Saúl", "cita": "1 Samuel 15:22", "frase": "El primer rey de Israel; aprendió que obedecer es mejor que los sacrificios.", "seccion": "Reyes de Israel", "plan": "gratis", "color": "#E5383B", "quien": "Saúl fue el primer rey de Israel. Era alto y fuerte, pero no siempre obedeció a Dios, y por eso perdió su reino.", "leer": "1 Samuel 9–10; 15:22-23", "recordamos": "Ser el primer rey de Israel.", "valor": "Obediencia", "sabias": "Saúl era más alto que todo el pueblo: le sacaba una cabeza a los demás.", "aprendo": "Obedecer a Dios es más importante que verse importante."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-040', '{"numero": 40, "nombre": "Jonatán", "cita": "1 Samuel 18:1-4", "frase": "El mejor amigo de David, leal y generoso.", "seccion": "Reyes de Israel", "plan": "gratis", "color": "#E5383B", "quien": "Jonatán era hijo del rey Saúl y el mejor amigo de David. Lo protegió aunque eso significaba no llegar a ser rey.", "leer": "1 Samuel 18:1-4; 20:1-42", "recordamos": "Ser el amigo fiel de David.", "valor": "Amistad", "sabias": "Jonatán le regaló a David su manto, su espada, su arco y su cinturón.", "aprendo": "Un buen amigo se alegra con los triunfos de los demás."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-041', '{"numero": 41, "nombre": "David", "cita": "1 Samuel 16:1-13", "frase": "El pastorcito que llegó a ser rey: Dios mira el corazón.", "seccion": "Reyes de Israel", "plan": "gratis", "color": "#E5383B", "quien": "David comenzó como pastor de ovejas, pero Dios tenía grandes planes para su vida. Llegó a ser rey de Israel y es recordado por su enorme confianza en Dios.", "leer": "1 Samuel 16–17", "recordamos": "Derrotar a Goliat y convertirse en rey.", "valor": "Confianza en Dios", "sabias": "David también tocaba el arpa y escribió muchos salmos.", "aprendo": "Puedo confiar en Dios incluso cuando enfrento algo que parece demasiado grande."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-042', '{"numero": 42, "nombre": "Goliat", "cita": "1 Samuel 17:41-50", "frase": "El gigante que cayó ante David, que confiaba en Dios.", "seccion": "Reyes de Israel", "plan": "gratis", "color": "#E5383B", "quien": "Goliat era un gigante filisteo que se burlaba de Dios y de Israel. Nadie se atrevía a enfrentarlo hasta que llegó el joven David.", "leer": "1 Samuel 17:1-51", "recordamos": "Ser el gigante vencido con una piedra.", "valor": "Humildad", "sabias": "Goliat medía cerca de 3 metros y su armadura pesaba unos 57 kilos.", "aprendo": "No hay gigante más grande que mi Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-043', '{"numero": 43, "nombre": "Mical", "cita": "1 Samuel 19:11-17", "frase": "Ayudó a David a escapar de Saúl.", "seccion": "Reyes de Israel", "plan": "gratis", "color": "#E5383B", "quien": "Mical era hija del rey Saúl y esposa de David. Cuando su papá quiso hacerle daño a David, ella lo ayudó a escapar por una ventana.", "leer": "1 Samuel 18:20; 19:11-17", "recordamos": "Ayudar a David a escapar.", "valor": "Protección", "sabias": "Mical puso una estatua en la cama de David para engañar a los soldados.", "aprendo": "Puedo ayudar a quien está en peligro."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-044', '{"numero": 44, "nombre": "Abigail", "cita": "1 Samuel 25:23-35", "frase": "Sabia y prudente, evitó una pelea con palabras amables.", "seccion": "Reyes de Israel", "plan": "gratis", "color": "#E5383B", "quien": "Abigail fue una mujer sabia que salió al encuentro de David con comida y palabras amables, y así evitó una pelea.", "leer": "1 Samuel 25:2-42", "recordamos": "Calmar a David con sabiduría.", "valor": "Prudencia", "sabias": "Abigail llevó 200 panes, 5 ovejas y 200 tortas de higos.", "aprendo": "Las palabras amables pueden detener una pelea."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-045', '{"numero": 45, "nombre": "Natán", "cita": "2 Samuel 12:1-13", "frase": "Profeta valiente que ayudó a David a reconocer su pecado.", "seccion": "Reyes de Israel", "plan": "gratis", "color": "#E5383B", "quien": "Natán fue el profeta del rey David. Con una historia sobre una ovejita lo ayudó a reconocer su pecado.", "leer": "2 Samuel 7:1-17; 12:1-13", "recordamos": "Contarle a David la historia de la ovejita.", "valor": "Sinceridad", "sabias": "Natán también ayudó a que Salomón fuera rey.", "aprendo": "Decir la verdad con amor ayuda a otros a volver a Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-046', '{"numero": 46, "nombre": "Absalón", "cita": "2 Samuel 15:1-14", "frase": "Hijo de David que se rebeló; nos enseña a honrar a nuestros padres.", "seccion": "Reyes de Israel", "plan": "gratis", "color": "#E5383B", "quien": "Absalón era hijo del rey David. Era muy admirado, pero se rebeló contra su papá para quitarle el trono.", "leer": "2 Samuel 15:1-14; 18:9-15", "recordamos": "Rebelarse contra su padre.", "valor": "Honrar a los padres", "sabias": "Su cabello era tan largo que se lo cortaba una vez al año.", "aprendo": "Honro a mis padres y no busco ser más que otros."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-047', '{"numero": 47, "nombre": "Salomón", "cita": "1 Reyes 3:5-14", "frase": "Le pidió a Dios sabiduría, y Dios se la dio.", "seccion": "Reyes de Israel", "plan": "gratis", "color": "#E5383B", "quien": "Salomón fue hijo de David y rey de Israel. Cuando Dios le ofreció lo que quisiera, pidió sabiduría, y construyó el templo de Jerusalén.", "leer": "1 Reyes 3:5-28; 6:1, 14", "recordamos": "Pedir sabiduría y construir el templo.", "valor": "Sabiduría", "sabias": "Salomón escribió muchos proverbios y canciones.", "aprendo": "Puedo pedirle a Dios sabiduría para tomar buenas decisiones."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-048', '{"numero": 48, "nombre": "Reina de Sabá", "cita": "1 Reyes 10:1-10", "frase": "Viajó desde lejos para conocer la sabiduría que Dios dio a Salomón.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "La reina de Sabá viajó desde muy lejos para conocer la sabiduría que Dios le había dado a Salomón, y alabó al Dios de Israel.", "leer": "1 Reyes 10:1-13", "recordamos": "Visitar a Salomón con muchos regalos.", "valor": "Búsqueda de la verdad", "sabias": "Jesús la menciona como la «reina del sur».", "aprendo": "Vale la pena buscar a Dios y aprender de Él."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-049', '{"numero": 49, "nombre": "Roboam", "cita": "1 Reyes 12:1-17", "frase": "No escuchó los buenos consejos y el reino se dividió.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Roboam fue hijo de Salomón. No escuchó el consejo de los ancianos y fue duro con el pueblo, y el reino se dividió en dos.", "leer": "1 Reyes 12:1-24", "recordamos": "Que en su tiempo se dividió el reino.", "valor": "Escuchar consejos", "sabias": "Diez tribus se fueron al norte; solo Judá y Benjamín se quedaron con él.", "aprendo": "Escucho los buenos consejos de los mayores."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-050', '{"numero": 50, "nombre": "Jeroboam", "cita": "1 Reyes 12:25-33", "frase": "Rey del norte que alejó al pueblo de Dios con ídolos.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Jeroboam fue el primer rey del reino del norte, Israel. Para que el pueblo no fuera a Jerusalén, hizo becerros de oro y lo alejó de Dios.", "leer": "1 Reyes 11:26-31; 12:25-33", "recordamos": "Hacer becerros de oro.", "valor": "Fidelidad a Dios", "sabias": "Un profeta rompió un manto en 12 pedazos y le dio 10: las tribus que gobernaría.", "aprendo": "Nada debe ocupar el lugar de Dios en mi corazón."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-051', '{"numero": 51, "nombre": "Elías", "cita": "1 Reyes 18:20-39", "frase": "Oró en el monte Carmelo y Dios respondió con fuego del cielo.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Elías fue un profeta valiente en tiempos del rey Acab. Dios lo alimentó con cuervos y respondió con fuego del cielo en el monte Carmelo.", "leer": "1 Reyes 17:1-6; 18:20-39", "recordamos": "El fuego del cielo y el carro de fuego.", "valor": "Valentía", "sabias": "Elías subió al cielo en un torbellino, con un carro de fuego.", "aprendo": "Dios responde cuando oro con fe."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-052', '{"numero": 52, "nombre": "Acab", "cita": "1 Reyes 21:1-29", "frase": "Rey que se alejó de Dios; Dios aún le dio oportunidad de arrepentirse.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Acab fue un rey de Israel que se alejó de Dios y adoró a Baal. Aun así, Dios le dio oportunidades para arrepentirse.", "leer": "1 Reyes 16:29-33; 21:1-29", "recordamos": "Ser el rey que enfrentó a Elías.", "valor": "Arrepentimiento", "sabias": "Acab se puso triste y no quiso comer porque no le vendieron una viña.", "aprendo": "Dios siempre me da la oportunidad de volver a Él."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-053', '{"numero": 53, "nombre": "Jezabel", "cita": "1 Reyes 19:1-3", "frase": "Reina que persiguió a los profetas de Dios.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Jezabel fue una reina que adoraba a Baal y persiguió a los profetas de Dios, incluso a Elías.", "leer": "1 Reyes 18:4; 19:1-3; 21:5-16", "recordamos": "Perseguir a los profetas de Dios.", "valor": "Humildad", "sabias": "Jezabel era hija de un rey de Sidón.", "aprendo": "Uso lo que tengo para hacer el bien, no para dañar a otros."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-054', '{"numero": 54, "nombre": "Eliseo", "cita": "2 Reyes 2:9-15", "frase": "Recibió el manto de Elías y una doble porción de su espíritu.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Eliseo fue el ayudante de Elías y recibió su manto. Dios hizo muchos milagros por medio de él para ayudar a las personas.", "leer": "2 Reyes 2:9-15; 4:1-7", "recordamos": "Recibir el manto de Elías y una doble porción de su espíritu.", "valor": "Servicio", "sabias": "Eliseo hizo flotar un hacha de hierro en el río.", "aprendo": "Dios puede usarme para ayudar a otros."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-055', '{"numero": 55, "nombre": "Naamán", "cita": "2 Reyes 5:1-14", "frase": "Se lavó siete veces en el Jordán y Dios lo sanó.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Naamán era un general sirio enfermo de lepra. Gracias a una niña que le habló de Dios, fue a ver a Eliseo y se lavó siete veces en el río Jordán.", "leer": "2 Reyes 5:1-15", "recordamos": "Ser sanado en el río Jordán.", "valor": "Humildad", "sabias": "Una niña esclava fue quien le contó que Dios podía sanarlo.", "aprendo": "Aunque sea niño, puedo contarle a otros del amor de Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-056', '{"numero": 56, "nombre": "Jonás", "cita": "Jonás 1:1-3; 2:1-10", "frase": "Huyó de Dios, pasó tres días en un gran pez y luego obedeció.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Jonás fue un profeta que huyó cuando Dios lo envió a Nínive. Un gran pez se lo tragó, oró desde adentro y después obedeció.", "leer": "Jonás 1–3", "recordamos": "Pasar tres días dentro de un gran pez.", "valor": "Obediencia", "sabias": "Toda la ciudad de Nínive se arrepintió, ¡incluso el rey!", "aprendo": "Es mejor obedecer a Dios a la primera."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-057', '{"numero": 57, "nombre": "Amós", "cita": "Amós 5:24", "frase": "Pastor y profeta que pidió que la justicia corriera como un río.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Amós era pastor y cultivaba higos. Dios lo llamó a ser profeta para pedir justicia y cuidado por los pobres.", "leer": "Amós 1:1; 5:24; 7:14-15", "recordamos": "Pedir que la justicia corriera como un río.", "valor": "Justicia", "sabias": "Amós dijo: «No soy profeta, soy pastor», pero Dios lo envió igual.", "aprendo": "Dios me pide tratar a todos con justicia."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-058', '{"numero": 58, "nombre": "Oseas", "cita": "Oseas 14:1-4", "frase": "Profeta que habló del amor fiel de Dios que siempre nos llama a volver.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Oseas fue un profeta que enseñó cuánto ama Dios a su pueblo, aunque el pueblo se alejaba de Él.", "leer": "Oseas 11:1-4; 14:1-4", "recordamos": "Mostrar el amor fiel de Dios.", "valor": "Fidelidad", "sabias": "Oseas comparó a Dios con un papá que enseña a caminar a su hijo pequeño.", "aprendo": "El amor de Dios por mí nunca se acaba."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-059', '{"numero": 59, "nombre": "Isaías", "cita": "Isaías 6:8", "frase": "Dijo: «Aquí estoy, envíame a mí», y anunció la venida del Mesías.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Isaías fue un gran profeta. Vio la gloria de Dios en el templo y dijo «Aquí estoy, envíame a mí». Anunció la venida de Jesús muchos años antes.", "leer": "Isaías 6:1-8; 9:6; 53:5", "recordamos": "Anunciar el nacimiento del Mesías.", "valor": "Disposición", "sabias": "Isaías escribió sobre Jesús unos 700 años antes de que naciera.", "aprendo": "Puedo decirle a Dios: «Aquí estoy, úsame»."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-060', '{"numero": 60, "nombre": "Miqueas", "cita": "Miqueas 6:8", "frase": "Enseñó a hacer justicia, amar la misericordia y caminar humildes con Dios.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Miqueas fue un profeta de un pueblo pequeño. Anunció que el Mesías nacería en Belén y enseñó lo que Dios pide.", "leer": "Miqueas 5:2; 6:8", "recordamos": "Anunciar que Jesús nacería en Belén.", "valor": "Humildad", "sabias": "Los sabios que buscaban a Jesús encontraron Belén gracias a Miqueas.", "aprendo": "Dios me pide hacer lo justo, amar la misericordia y ser humilde."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-061', '{"numero": 61, "nombre": "Ezequías", "cita": "2 Reyes 18:1-7", "frase": "Rey que confió en Dios y oró cuando estaba en peligro.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Ezequías fue un rey bueno de Judá que quitó los ídolos y confió en Dios. Cuando un ejército enorme lo amenazó, oró y Dios lo salvó.", "leer": "2 Reyes 18:1-7; 19:14-19; 20:1-6", "recordamos": "Orar con la carta del enemigo frente a Dios.", "valor": "Confianza en Dios", "sabias": "Construyó un túnel de agua bajo Jerusalén que todavía existe.", "aprendo": "Puedo llevarle a Dios mis problemas en oración."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-062', '{"numero": 62, "nombre": "Josías", "cita": "2 Reyes 22:1-2; 23:1-3", "frase": "Fue rey a los 8 años y llevó al pueblo de vuelta a la Palabra de Dios.", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Josías llegó a ser rey cuando tenía solo 8 años. Encontraron el libro de la ley en el templo y él guió al pueblo a volver a Dios.", "leer": "2 Reyes 22:1-13; 23:1-3", "recordamos": "Ser rey niño y amar la Palabra de Dios.", "valor": "Amor por la Palabra", "sabias": "Josías tenía 8 años cuando empezó a reinar.", "aprendo": "Aunque sea niño, puedo amar la Palabra de Dios y seguirla."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-063', '{"numero": 63, "nombre": "Jeremías", "cita": "Jeremías 1:4-8", "frase": "Dios lo llamó desde joven: «No digas: soy un niño».", "seccion": "Reyes y profetas", "plan": "gratis", "color": "#F2B705", "quien": "Jeremías fue llamado por Dios cuando era joven. Anunció los mensajes de Dios aunque la gente no quería escucharlo.", "leer": "Jeremías 1:4-10; 29:11", "recordamos": "Ser el profeta llorón y valiente.", "valor": "Perseverancia", "sabias": "Dios le dijo que lo conocía desde antes de nacer.", "aprendo": "Dios tiene buenos planes para mí."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-064', '{"numero": 64, "nombre": "Daniel", "cita": "Daniel 6:10-23", "frase": "Siguió orando a Dios, y Dios cerró la boca de los leones.", "seccion": "Exilio y regreso", "plan": "gratis", "color": "#1AA3A3", "quien": "Daniel fue llevado a Babilonia cuando era joven. Siguió orando a Dios tres veces al día aunque estaba prohibido, y Dios lo libró de los leones.", "leer": "Daniel 1:8-17; 6:10-23", "recordamos": "Salir sano del foso de los leones.", "valor": "Fidelidad", "sabias": "Daniel también interpretaba sueños y vio visiones del futuro.", "aprendo": "Sigo amando a Dios aunque otros no lo hagan."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-065', '{"numero": 65, "nombre": "Sadrac", "cita": "Daniel 3:16-27", "frase": "No se inclinó ante la estatua; Dios lo protegió en el horno de fuego.", "seccion": "Exilio y regreso", "plan": "gratis", "color": "#1AA3A3", "quien": "Sadrac era amigo de Daniel en Babilonia. Junto a Mesac y Abed-nego se negó a adorar una estatua de oro.", "leer": "Daniel 1:6-7; 3:1-30", "recordamos": "No inclinarse ante la estatua de oro.", "valor": "Fidelidad", "sabias": "Su nombre hebreo era Ananías.", "aprendo": "Puedo decir «no» a lo que ofende a Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-066', '{"numero": 66, "nombre": "Mesac", "cita": "Daniel 3:16-27", "frase": "Fiel a Dios junto a sus amigos, salió del horno sin quemarse.", "seccion": "Exilio y regreso", "plan": "gratis", "color": "#1AA3A3", "quien": "Mesac fue lanzado al horno de fuego con sus amigos por no adorar la estatua del rey, y Dios lo protegió.", "leer": "Daniel 3:16-27", "recordamos": "Salir del horno sin olor a humo.", "valor": "Valentía", "sabias": "Su nombre hebreo era Misael.", "aprendo": "Con buenos amigos es más fácil ser fiel a Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-067', '{"numero": 67, "nombre": "Abed-nego", "cita": "Daniel 3:16-27", "frase": "En el fuego apareció un cuarto hombre junto a él y sus amigos.", "seccion": "Exilio y regreso", "plan": "gratis", "color": "#1AA3A3", "quien": "Abed-nego confió en Dios junto a sus amigos dentro del horno. El rey vio a un cuarto hombre caminando con ellos en el fuego.", "leer": "Daniel 3:19-30", "recordamos": "El cuarto hombre en el horno de fuego.", "valor": "Confianza", "sabias": "Su nombre hebreo era Azarías.", "aprendo": "Dios está conmigo aun en los momentos más difíciles."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-068', '{"numero": 68, "nombre": "Ezequiel", "cita": "Ezequiel 37:1-14", "frase": "Vio un valle de huesos secos volver a la vida por el poder de Dios.", "seccion": "Exilio y regreso", "plan": "gratis", "color": "#1AA3A3", "quien": "Ezequiel fue un profeta que vivió con su pueblo en Babilonia. Dios le mostró visiones increíbles, como un valle de huesos que volvía a la vida.", "leer": "Ezequiel 37:1-14", "recordamos": "La visión del valle de huesos secos.", "valor": "Esperanza", "sabias": "Ezequiel vio ruedas llenas de ojos en una visión de la gloria de Dios.", "aprendo": "Dios puede dar vida nueva a lo que parece perdido."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-069', '{"numero": 69, "nombre": "Nabucodonosor", "cita": "Daniel 4:34-37", "frase": "Rey de Babilonia que terminó alabando al Dios del cielo.", "seccion": "Exilio y regreso", "plan": "gratis", "color": "#1AA3A3", "quien": "Nabucodonosor fue un rey muy poderoso de Babilonia. Era orgulloso, pero Dios lo humilló y al final alabó al Dios del cielo.", "leer": "Daniel 2; 3; 4:34-37", "recordamos": "Construir la estatua de oro y alabar a Dios.", "valor": "Humildad", "sabias": "Se le atribuyen los famosos jardines colgantes de Babilonia.", "aprendo": "Todo lo bueno que tengo viene de Dios."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-070', '{"numero": 70, "nombre": "Ester", "cita": "Ester 4:14-16", "frase": "Reina valiente que arriesgó su vida para salvar a su pueblo.", "seccion": "Exilio y regreso", "plan": "gratis", "color": "#1AA3A3", "quien": "Ester fue una joven judía que llegó a ser reina de Persia. Arriesgó su vida al hablar con el rey para salvar a su pueblo.", "leer": "Ester 4:12-17; 7:1-6", "recordamos": "Salvar a su pueblo con valentía.", "valor": "Valentía", "sabias": "Ester ayunó tres días antes de presentarse ante el rey.", "aprendo": "Dios me pone en lugares especiales para ayudar a otros."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-071', '{"numero": 71, "nombre": "Mardoqueo", "cita": "Ester 4:13-14", "frase": "Primo de Ester que la animó: «para esta hora has llegado».", "seccion": "Exilio y regreso", "plan": "gratis", "color": "#1AA3A3", "quien": "Mardoqueo era primo de Ester y la crió como a una hija. Descubrió un plan contra el rey y animó a Ester a ser valiente.", "leer": "Ester 2:5-7, 21-23; 4:13-14", "recordamos": "Decirle a Ester «para esta hora has llegado».", "valor": "Integridad", "sabias": "El rey lo honró paseándolo por la ciudad en su propio caballo.", "aprendo": "Hacer lo correcto siempre vale la pena."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-072', '{"numero": 72, "nombre": "Esdras", "cita": "Esdras 7:10", "frase": "Estudió y enseñó la Palabra de Dios al pueblo que regresó.", "seccion": "Exilio y regreso", "plan": "gratis", "color": "#1AA3A3", "quien": "Esdras fue un sacerdote y maestro que regresó a Jerusalén. Estudió la Palabra de Dios, la vivió y la enseñó al pueblo.", "leer": "Esdras 7:6-10; Nehemías 8:1-8", "recordamos": "Leer la ley de Dios al pueblo.", "valor": "Amor por la Palabra", "sabias": "Esdras leyó la ley desde temprano hasta el mediodía, sobre una plataforma de madera.", "aprendo": "Estudio la Biblia para vivirla y enseñarla."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-073', '{"numero": 73, "nombre": "Nehemías", "cita": "Nehemías 2:17-18", "frase": "Oró y trabajó para reconstruir los muros de Jerusalén.", "seccion": "Exilio y regreso", "plan": "gratis", "color": "#1AA3A3", "quien": "Nehemías trabajaba para el rey de Persia. Se puso triste al saber que los muros de Jerusalén estaban destruidos, oró y fue a reconstruirlos.", "leer": "Nehemías 1:3-11; 2:17-18; 6:15", "recordamos": "Reconstruir los muros en solo 52 días.", "valor": "Perseverancia", "sabias": "Los constructores trabajaban con una herramienta en una mano y un arma en la otra.", "aprendo": "Con oración y trabajo en equipo podemos hacer grandes cosas."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-074', '{"numero": 74, "nombre": "Zacarías", "cita": "Lucas 1:5-20", "frase": "Sacerdote y padre de Juan el Bautista; un ángel le anunció su nacimiento.", "seccion": "La llegada de Jesús", "plan": "gratis", "color": "#F59E0B", "quien": "Zacarías era sacerdote y esposo de Elisabet. Un ángel le anunció que tendrían un hijo, pero no creyó y quedó mudo hasta que nació Juan.", "leer": "Lucas 1:5-25, 57-80", "recordamos": "Quedar mudo hasta el nacimiento de Juan.", "valor": "Fe", "sabias": "Cuando nació su hijo, escribió en una tablilla: «Su nombre es Juan».", "aprendo": "Dios cumple sus promesas aunque parezcan imposibles."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-075', '{"numero": 75, "nombre": "Elisabet", "cita": "Lucas 1:39-45", "frase": "Madre de Juan el Bautista; se llenó de alegría al recibir a María.", "seccion": "La llegada de Jesús", "plan": "gratis", "color": "#F59E0B", "quien": "Elisabet era prima de María y la mamá de Juan el Bautista. Cuando María la visitó, el bebé saltó de alegría en su vientre.", "leer": "Lucas 1:39-45", "recordamos": "Recibir a María con alegría.", "valor": "Alegría", "sabias": "Elisabet tuvo a Juan cuando ya era anciana.", "aprendo": "Me alegro con las bendiciones de los demás."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-076', '{"numero": 76, "nombre": "María", "cita": "Lucas 1:26-38", "frase": "Dijo «sí» a Dios y fue la madre de Jesús.", "seccion": "La llegada de Jesús", "plan": "gratis", "color": "#F59E0B", "quien": "María era una joven de Nazaret. El ángel Gabriel le anunció que sería la mamá de Jesús, y ella respondió con fe: «Aquí está la sierva del Señor».", "leer": "Lucas 1:26-38; 2:1-19", "recordamos": "Ser la madre de Jesús.", "valor": "Disposición", "sabias": "María guardaba todas estas cosas en su corazón.", "aprendo": "Puedo decirle «sí» a lo que Dios me pida."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-077', '{"numero": 77, "nombre": "José", "cita": "Mateo 1:18-25", "frase": "Carpintero obediente que cuidó a María y a Jesús.", "seccion": "La llegada de Jesús", "plan": "gratis", "color": "#F59E0B", "quien": "José era un carpintero de Nazaret, esposo de María. Obedeció a Dios en sueños y cuidó a Jesús como su papá en la tierra.", "leer": "Mateo 1:18-25; 2:13-15", "recordamos": "Cuidar a María y a Jesús.", "valor": "Obediencia", "sabias": "Dios le habló a José en sueños cuatro veces.", "aprendo": "Obedecer a Dios a tiempo protege a mi familia."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-078', '{"numero": 78, "nombre": "Juan el Bautista", "cita": "Juan 1:29", "frase": "Preparó el camino y presentó a Jesús: «Este es el Cordero de Dios».", "seccion": "La llegada de Jesús", "plan": "gratis", "color": "#F59E0B", "quien": "Juan el Bautista vivía en el desierto, vestía piel de camello y comía langostas y miel. Preparó el camino para Jesús y lo bautizó en el río Jordán.", "leer": "Mateo 3:1-17; Juan 1:29", "recordamos": "Bautizar a Jesús.", "valor": "Humildad", "sabias": "Juan dijo: «Es necesario que Él crezca y que yo disminuya».", "aprendo": "Quiero que los demás vean a Jesús en mí."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-079', '{"numero": 79, "nombre": "Jesús", "cita": "Juan 3:16", "frase": "El Hijo de Dios, que vino a salvarnos porque nos ama.", "seccion": "La llegada de Jesús", "plan": "gratis", "color": "#F59E0B", "quien": "Jesús es el Hijo de Dios, que vino al mundo a salvarnos. Sanó a enfermos, enseñó el amor de Dios, murió en la cruz y resucitó.", "leer": "Lucas 2:1-20; Juan 3:16; Mateo 28:1-10", "recordamos": "Dar su vida por nosotros y resucitar.", "valor": "Amor", "sabias": "Jesús es el centro de toda la Biblia: ¡todas las historias apuntan a Él!", "aprendo": "Jesús me ama y quiere ser mi mejor amigo."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-080', '{"numero": 80, "nombre": "Pedro", "cita": "Mateo 16:15-18", "frase": "Pescador que reconoció a Jesús como el Cristo, el Hijo de Dios.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Pedro era pescador y fue uno de los primeros discípulos de Jesús. Caminó sobre el agua y, aunque negó a Jesús, fue perdonado y se convirtió en un gran líder.", "leer": "Mateo 14:22-33; 16:15-18; Juan 21:15-17", "recordamos": "Caminar sobre el agua y predicar en Pentecostés.", "valor": "Valentía", "sabias": "Jesús le cambió el nombre de Simón a Pedro, que significa «piedra».", "aprendo": "Jesús me perdona y me da una nueva oportunidad."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-081', '{"numero": 81, "nombre": "Andrés", "cita": "Juan 1:40-42", "frase": "Lo primero que hizo fue llevar a su hermano Pedro a Jesús.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Andrés era pescador, hermano de Pedro. Cuando conoció a Jesús, lo primero que hizo fue ir a buscar a su hermano.", "leer": "Juan 1:35-42; 6:8-9", "recordamos": "Llevar a su hermano Pedro a Jesús.", "valor": "Evangelismo", "sabias": "Andrés llevó a Jesús al niño de los cinco panes y dos peces.", "aprendo": "Puedo invitar a otros a conocer a Jesús."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-082', '{"numero": 82, "nombre": "Santiago, hijo de Zebedeo", "cita": "Marcos 1:19-20", "frase": "Pescador que dejó sus redes para seguir a Jesús.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Santiago era pescador e hijo de Zebedeo. Dejó sus redes para seguir a Jesús y estuvo con Él en momentos muy especiales.", "leer": "Marcos 1:19-20; 9:2-8", "recordamos": "Ser uno de los tres amigos más cercanos de Jesús.", "valor": "Entrega", "sabias": "Jesús llamó a Santiago y a Juan «hijos del trueno».", "aprendo": "Seguir a Jesús es lo más importante."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-083', '{"numero": 83, "nombre": "Juan, hijo de Zebedeo", "cita": "1 Juan 4:7", "frase": "El discípulo amado; nos enseñó a amarnos unos a otros.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Juan era pescador, hermano de Santiago. Fue llamado «el discípulo amado» y escribió un evangelio, cartas y el libro de Apocalipsis.", "leer": "Juan 13:23; 19:26-27; 1 Juan 4:7-8", "recordamos": "Ser el discípulo amado y hablar del amor.", "valor": "Amor", "sabias": "Jesús le encargó cuidar a su madre María.", "aprendo": "Dios es amor y quiere que nos amemos unos a otros."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-084', '{"numero": 84, "nombre": "Felipe", "cita": "Juan 1:43-46", "frase": "Invitó a su amigo Natanael: «Ven y ve».", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Felipe era de Betsaida, como Pedro y Andrés. Cuando Jesús lo llamó, fue a invitar a su amigo Natanael: «Ven y ve».", "leer": "Juan 1:43-46; 6:5-7; 14:8-9", "recordamos": "Invitar a su amigo a conocer a Jesús.", "valor": "Amistad", "sabias": "Jesús le preguntó a Felipe dónde comprarían pan para 5.000 personas.", "aprendo": "Puedo invitar a mis amigos a ver lo bueno que es Jesús."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-085', '{"numero": 85, "nombre": "Bartolomé", "cita": "Mateo 10:1-4", "frase": "Uno de los doce apóstoles que Jesús eligió.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Bartolomé fue uno de los doce apóstoles que Jesús eligió. Muchos creen que es el mismo Natanael, a quien Jesús vio debajo de una higuera.", "leer": "Mateo 10:1-4; Juan 1:45-49", "recordamos": "Ser uno de los doce apóstoles.", "valor": "Sinceridad", "sabias": "Jesús dijo de Natanael que era un hombre en quien no había engaño.", "aprendo": "Jesús me conoce y me llama por mi nombre."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-086', '{"numero": 86, "nombre": "Mateo", "cita": "Mateo 9:9", "frase": "Cobrador de impuestos que lo dejó todo para seguir a Jesús.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Mateo era cobrador de impuestos, y la gente no lo quería. Jesús lo llamó, él lo dejó todo y luego escribió el primer evangelio.", "leer": "Mateo 9:9-13", "recordamos": "Dejar su mesa de impuestos para seguir a Jesús.", "valor": "Cambio de vida", "sabias": "Mateo también se llamaba Leví e hizo una gran fiesta para Jesús.", "aprendo": "Jesús me ama tal como soy y me ayuda a cambiar."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-087', '{"numero": 87, "nombre": "Tomás", "cita": "Juan 20:24-29", "frase": "Tuvo dudas, y al ver a Jesús resucitado dijo: «¡Señor mío y Dios mío!».", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Tomás fue uno de los doce. No creyó que Jesús había resucitado hasta verlo, y cuando lo vio dijo: «¡Señor mío y Dios mío!».", "leer": "Juan 11:16; 20:24-29", "recordamos": "Pasar de la duda a la fe.", "valor": "Fe", "sabias": "Jesús dijo: «Bienaventurados los que no vieron y creyeron».", "aprendo": "Puedo llevarle mis dudas a Jesús."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-088', '{"numero": 88, "nombre": "Santiago, hijo de Alfeo", "cita": "Mateo 10:1-4", "frase": "Apóstol de Jesús; nos recuerda que todo servicio importa.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Santiago, hijo de Alfeo, fue uno de los doce apóstoles. La Biblia cuenta poco de él, pero siguió a Jesús fielmente.", "leer": "Mateo 10:1-4; Hechos 1:13", "recordamos": "Ser un apóstol fiel.", "valor": "Fidelidad", "sabias": "Se le conoce como «Santiago el menor».", "aprendo": "No tengo que ser famoso para servir a Jesús."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-089', '{"numero": 89, "nombre": "Simón el Zelote", "cita": "Lucas 6:12-16", "frase": "Apóstol que Jesús eligió después de orar toda una noche.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Simón el Zelote fue uno de los doce apóstoles. Antes quería luchar contra los romanos, pero Jesús le enseñó un camino de amor.", "leer": "Lucas 6:12-16; Hechos 1:13", "recordamos": "Ser un apóstol con un gran celo.", "valor": "Paz", "sabias": "Jesús eligió a sus doce apóstoles después de orar toda una noche.", "aprendo": "Jesús transforma mi pasión en amor por los demás."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-090', '{"numero": 90, "nombre": "Judas Tadeo", "cita": "Juan 14:22-23", "frase": "Apóstol que preguntó a Jesús y aprendió que Dios vive con quien lo ama.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Judas Tadeo fue uno de los doce apóstoles. En la última cena le hizo a Jesús una pregunta importante y escuchó su respuesta de amor.", "leer": "Juan 14:22-23; Lucas 6:16", "recordamos": "Preguntarle a Jesús en la última cena.", "valor": "Curiosidad", "sabias": "No debe confundirse con Judas Iscariote: eran dos personas distintas.", "aprendo": "Puedo hacerle preguntas a Jesús y aprender de Él."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-091', '{"numero": 91, "nombre": "Judas Iscariote", "cita": "Mateo 26:14-16", "frase": "Traicionó a Jesús por dinero; nos enseña a cuidar nuestro corazón.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Judas Iscariote fue uno de los doce apóstoles y cuidaba la bolsa del dinero. Traicionó a Jesús por treinta monedas de plata.", "leer": "Mateo 26:14-16, 47-50", "recordamos": "Traicionar a Jesús.", "valor": "Lealtad", "sabias": "Judas entregó a Jesús con un beso.", "aprendo": "Cuido mi corazón para que nada sea más importante que Jesús."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-092', '{"numero": 92, "nombre": "María Magdalena", "cita": "Juan 20:11-18", "frase": "La primera en ver a Jesús resucitado y contar la buena noticia.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "María Magdalena fue liberada por Jesús y lo siguió desde entonces. Fue la primera en ver a Jesús resucitado y en anunciarlo.", "leer": "Lucas 8:1-3; Juan 20:11-18", "recordamos": "Ser la primera en ver a Jesús resucitado.", "valor": "Gratitud", "sabias": "Al principio confundió a Jesús con el jardinero.", "aprendo": "Puedo contarle a otros que Jesús está vivo."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-093', '{"numero": 93, "nombre": "Marta", "cita": "Lucas 10:38-42", "frase": "Servía con mucho trabajo, y Jesús le enseñó lo más importante.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Marta era hermana de María y Lázaro, y amiga de Jesús. Le gustaba servir y recibir a Jesús en su casa en Betania.", "leer": "Lucas 10:38-42; Juan 11:20-27", "recordamos": "Servir a Jesús en su casa.", "valor": "Servicio", "sabias": "Marta dijo una gran declaración de fe: «Tú eres el Cristo, el Hijo de Dios».", "aprendo": "Servir es bueno, pero estar con Jesús es lo más importante."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-094', '{"numero": 94, "nombre": "María de Betania", "cita": "Lucas 10:38-42", "frase": "Se sentó a los pies de Jesús para escuchar su Palabra.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "María de Betania era hermana de Marta y Lázaro. Le encantaba sentarse a los pies de Jesús para escucharlo y le ungió los pies con un perfume muy caro.", "leer": "Lucas 10:38-42; Juan 12:1-8", "recordamos": "Escuchar a Jesús y ungirlo con perfume.", "valor": "Adoración", "sabias": "El perfume que usó valía casi el sueldo de un año.", "aprendo": "Escuchar a Jesús es la mejor parte."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-095', '{"numero": 95, "nombre": "Lázaro", "cita": "Juan 11:38-44", "frase": "Amigo de Jesús: ¡Jesús lo resucitó después de cuatro días!", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Lázaro era amigo de Jesús y hermano de Marta y María. Murió, y después de cuatro días Jesús lo llamó desde la tumba y volvió a vivir.", "leer": "Juan 11:1-44", "recordamos": "Ser resucitado por Jesús.", "valor": "Esperanza", "sabias": "El versículo más corto de la Biblia está en su historia: «Jesús lloró».", "aprendo": "Jesús tiene poder sobre la muerte."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-096', '{"numero": 96, "nombre": "Zaqueo", "cita": "Lucas 19:1-10", "frase": "Se subió a un árbol para ver a Jesús y su vida cambió.", "seccion": "Jesús y sus discípulos", "plan": "gratis", "color": "#E0457B", "quien": "Zaqueo era un cobrador de impuestos rico y bajito. Se subió a un árbol para ver a Jesús, y Jesús fue a su casa. Su vida cambió para siempre.", "leer": "Lucas 19:1-10", "recordamos": "Subirse a un sicómoro para ver a Jesús.", "valor": "Arrepentimiento", "sabias": "Zaqueo devolvió cuatro veces lo que había cobrado de más.", "aprendo": "Cuando conozco a Jesús, quiero ser mejor persona."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-097', '{"numero": 97, "nombre": "Esteban", "cita": "Hechos 7:55-60", "frase": "Lleno del Espíritu Santo, perdonó a quienes lo atacaban.", "seccion": "La Iglesia comienza", "plan": "gratis", "color": "#F25C05", "quien": "Esteban era un joven lleno de fe y del Espíritu Santo. Ayudaba a repartir comida a las viudas y predicó con valentía sobre Jesús.", "leer": "Hechos 6:1-15; 7:55-60", "recordamos": "Perdonar a quienes lo atacaban.", "valor": "Perdón", "sabias": "Esteban vio los cielos abiertos y a Jesús de pie junto a Dios.", "aprendo": "Puedo perdonar como Jesús perdonó."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-098', '{"numero": 98, "nombre": "Pablo", "cita": "Hechos 9:1-19", "frase": "Se encontró con Jesús en el camino y llevó el evangelio por el mundo.", "seccion": "La Iglesia comienza", "plan": "gratis", "color": "#F25C05", "quien": "Pablo, antes llamado Saulo, perseguía a los cristianos. Jesús se le apareció en el camino a Damasco y cambió su vida. Llevó el evangelio a muchos países.", "leer": "Hechos 9:1-19; 2 Timoteo 4:7", "recordamos": "Su encuentro con Jesús y sus viajes misioneros.", "valor": "Valentía", "sabias": "Pablo escribió 13 cartas del Nuevo Testamento.", "aprendo": "Jesús puede cambiar a cualquier persona, y me envía a contarlo."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-099', '{"numero": 99, "nombre": "Bernabé", "cita": "Hechos 4:36-37", "frase": "Su nombre significa «hijo de consolación»; siempre animaba a los demás.", "seccion": "La Iglesia comienza", "plan": "gratis", "color": "#F25C05", "quien": "Bernabé era un hombre generoso que vendió su campo para ayudar a la iglesia. Siempre animaba a los demás y viajó con Pablo.", "leer": "Hechos 4:36-37; 9:26-27; 11:22-24", "recordamos": "Animar a todos y confiar en Pablo.", "valor": "Ánimo", "sabias": "Su nombre significa «hijo de consolación».", "aprendo": "Puedo animar a otros con mis palabras."}'::jsonb, now()),
  (public.central_id(), 'laminas', 'lamina-100', '{"numero": 100, "nombre": "Timoteo", "cita": "1 Timoteo 4:12", "frase": "Joven ejemplo de fe: «Que nadie te menosprecie por ser joven».", "seccion": "La Iglesia comienza", "plan": "gratis", "color": "#F25C05", "quien": "Timoteo aprendió la Palabra de Dios de su abuela Loida y su mamá Eunice. Fue ayudante de Pablo y líder de la iglesia siendo joven.", "leer": "2 Timoteo 1:5; 3:14-15; 1 Timoteo 4:12", "recordamos": "Ser un joven ejemplo de fe.", "valor": "Ejemplo", "sabias": "Pablo le escribió dos cartas que están en la Biblia.", "aprendo": "Aunque sea joven, puedo ser ejemplo para los demás."}'::jsonb, now())
